/* VNB SPORTS - OPTIMIZED JAVASCRIPT */
(function(){
'use strict';

// Utility functions
const $ = (selector) => document.querySelector(selector);
const $$ = (selector) => document.querySelectorAll(selector);

// Cart functionality
window.updateQuantity = function(id, change) {
    const input = $(`#qty-${id}`);
    if (!input) return;
    
    let currentQty = parseInt(input.value);
    let newQty = currentQty + change;
    if (newQty < 1) newQty = 1;
    
    input.value = newQty;
    
    // Show loading
    const btn = event.target;
    const originalText = btn.textContent;
    btn.textContent = '...';
    btn.disabled = true;
    
    fetch('/cart/update', {
        method: 'PATCH',
        headers: {
            'Content-Type': 'application/json',
            'X-CSRF-TOKEN': $('meta[name="csrf-token"]').getAttribute('content')
        },
        body: JSON.stringify({ id: id, quantity: newQty })
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            location.reload();
        }
    })
    .catch(() => {
        btn.textContent = originalText;
        btn.disabled = false;
        alert('Có lỗi xảy ra, vui lòng thử lại!');
    });
};

// Image modal functionality
window.openImageModal = function(imageSrc) {
    const modal = document.createElement('div');
    modal.className = 'image-modal';
    modal.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.8);display:flex;align-items:center;justify-content:center;z-index:9999;cursor:pointer';
    
    const img = document.createElement('img');
    img.src = imageSrc;
    img.style.cssText = 'max-width:90%;max-height:90%;object-fit:contain;border-radius:8px';
    
    modal.appendChild(img);
    document.body.appendChild(modal);
    
    modal.addEventListener('click', () => {
        document.body.removeChild(modal);
    });
};

// Form validation
window.validateForm = function(form) {
    const requiredFields = form.querySelectorAll('[required]');
    let isValid = true;
    
    requiredFields.forEach(field => {
        if (!field.value.trim()) {
            field.style.borderColor = '#dc3545';
            isValid = false;
        } else {
            field.style.borderColor = '#ddd';
        }
    });
    
    return isValid;
};

// Smooth scroll
window.smoothScrollTo = function(target) {
    const element = $(target);
    if (element) {
        element.scrollIntoView({ behavior: 'smooth' });
    }
};

// Loading state
window.showLoading = function(element) {
    element.classList.add('loading');
    element.disabled = true;
};

window.hideLoading = function(element) {
    element.classList.remove('loading');
    element.disabled = false;
};

// Toast notifications
window.showToast = function(message, type = 'info') {
    const toast = document.createElement('div');
    toast.className = `toast toast-${type}`;
    toast.style.cssText = 'position:fixed;top:20px;right:20px;padding:15px 20px;border-radius:5px;color:white;z-index:10000;transform:translateX(100%);transition:transform 0.3s';
    
    const colors = {
        success: '#28a745',
        error: '#dc3545',
        warning: '#ffc107',
        info: '#17a2b8'
    };
    
    toast.style.background = colors[type] || colors.info;
    toast.textContent = message;
    
    document.body.appendChild(toast);
    
    setTimeout(() => {
        toast.style.transform = 'translateX(0)';
    }, 100);
    
    setTimeout(() => {
        toast.style.transform = 'translateX(100%)';
        setTimeout(() => {
            if (document.body.contains(toast)) {
                document.body.removeChild(toast);
            }
        }, 300);
    }, 3000);
};

// Initialize on DOM ready
document.addEventListener('DOMContentLoaded', function() {
    // Auto-resize textareas
    $$('textarea').forEach(textarea => {
        textarea.addEventListener('input', function() {
            this.style.height = 'auto';
            this.style.height = this.scrollHeight + 'px';
        });
    });
    
    // Add loading states to forms
    $$('form').forEach(form => {
        form.addEventListener('submit', function(e) {
            const submitBtn = form.querySelector('button[type="submit"]');
            if (submitBtn && validateForm(form)) {
                showLoading(submitBtn);
            }
        });
    });
    
    // Lazy load images
    if ('IntersectionObserver' in window) {
        const imageObserver = new IntersectionObserver((entries, observer) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    const img = entry.target;
                    img.src = img.dataset.src;
                    img.classList.remove('lazy');
                    observer.unobserve(img);
                }
            });
        });
        
        $$('img[data-src]').forEach(img => {
            img.classList.add('lazy');
            imageObserver.observe(img);
        });
    }
    
    // Add click handlers for product images
    $$('.product-image').forEach(img => {
        img.addEventListener('click', function() {
            openImageModal(this.src);
        });
    });
});

})();